const items = $input.all();
const processedItems = [];

for (const item of items) {
  let text = item.json.text || item.json.data;

  if (typeof text === 'string' && text.length > 0) {
    text = text.replace(/_{5,}/g, '');
    text = text.replace(/^[ \t]+/gm, '');
    text = text.replace(/(\r\n|\n){3,}/g, '\n\n');
    text = text.replace(/\u0000/g, '');
    // Remove sintaxe de marcador [ASSET:ID] do texto ANTES de indexar no
    // Supabase. Se um documento fonte contiver esse padrao literal (ex.: um
    // catalogo de materiais com os marcadores escritos por engano), o chunk
    // indexado ensina o Agent a reproduzir a sintaxe do marcador quando esse
    // trecho e recuperado como contexto - causa raiz confirmada de respostas
    // com mais de um [ASSET:...] na mesma mensagem.
    text = text.replace(/\[\s*ASSET\s*:\s*[A-Za-z0-9_.-]+\s*\]/g, '');
    text = text.trim();

    item.json.data = text;
  }

  processedItems.push(item);
}

return processedItems;

